#include "unity.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_convert_safe_successful_conversion(void) {
    // Setup: valid inputs that satisfy the path conditions
    // Path conditions: output != NULL AND output_size >= 25 AND len < output_size
    char infix[] = "A+B";  // Simple infix expression
    size_t buffer_size = 50;  // Larger than minimum 25 and larger than result length
    char output_buffer[50];  // Allocated buffer

    // Test: call convert_safe
    int result = convert_safe(infix, output_buffer, buffer_size);

    // Assertions
    TEST_ASSERT_EQUAL_INT(0, result);  // Should return 0 for success
    // The output buffer should contain the postfix conversion result
    // We can't know the exact postfix string without calling convert,
    // but we can assert it's not empty (since convert should produce something for "A+B")
    TEST_ASSERT_NOT_EQUAL_STRING("", output_buffer);
    // Also ensure the string is null-terminated
    TEST_ASSERT_LESS_THAN(buffer_size, strlen(output_buffer) + 1);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_convert_safe_successful_conversion);
    return UNITY_END();
}
